  1	/**
  2	 * Módulo puro de wallet HD del exchange.
  3	 *
  4	 * Implementa, sin estado mutable ni I/O:
  5	 *  - BIP-39: generación (CSPRNG, 256 bits => 24 palabras), normalización NFKD, validación
  6	 *    (longitud / wordlist / checksum) y derivación de la seed binaria
  7	 *    (PBKDF2-HMAC-SHA512, 2048 iteraciones, 64 bytes).            [HU-06-01 RN-1..RN-3, RN-7]
  8	 *  - BIP-32: clave maestra y CKDpriv (hardened y normal) sobre secp256k1, con aritmética
  9	 *    modular en BigInt.                                            [HU-06-02 RN-1, RN-3, RN-8]
 10	 *  - BIP-44: path estándar de Ethereum `m/44'/60'/0'/0/address_index`
 11	 *    (coin type 60, red Sepolia chainId 11155111).                 [HU-06-02 RN-2, RN-7, RN-9]
 12	 *  - EIP-55: codificación con checksum de la dirección derivada de Keccak-256(X || Y).
 13	 *                                                                  [HU-06-02 RN-4]
 14	 *
 15	 * CUSTODIA (HU-06-01 RN-5, HU-06-02 RN-6): este módulo nunca serializa, retorna ni logea el
 16	 * mnemonic, la seed ni ninguna clave privada derivada. Los mensajes de error no contienen
 17	 * material secreto (ni el mnemonic ni palabras suyas). Solo salen del módulo datos públicos:
 18	 * la clave pública comprimida y la dirección.
 19	 */
 20	
 21	import { secp256k1 } from '@noble/curves/secp256k1';
 22	import { hmac } from '@noble/hashes/hmac';
 23	import { pbkdf2 as noblePbkdf2 } from '@noble/hashes/pbkdf2';
 24	import { sha512 } from '@noble/hashes/sha512';
 25	import { keccak_256 } from '@noble/hashes/sha3';
 26	import {
 27	  generateMnemonic as bip39GenerateMnemonic,
 28	  validateMnemonic as bip39ValidateMnemonic,
 29	} from '@scure/bip39';
 30	import { wordlist as ENGLISH_WORDLIST } from '@scure/bip39/wordlists/english';
 31	import { AppError, type ValidationIssue } from '../core/errors';
 32	
 33	// ---------------------------------------------------------------------------
 34	// Errores del módulo
 35	// ---------------------------------------------------------------------------
 36	
 37	/**
 38	 * Mnemonic BIP-39 inválido: longitud distinta de 24 palabras, palabra fuera del wordlist
 39	 * inglés o checksum incorrecto (HU-06-01 RN-2 => `VALIDATION_ERROR`).
 40	 *
 41	 * El mensaje NUNCA incluye el mnemonic ni ninguna de sus palabras (RN-5).
 42	 */
 43	export class MnemonicValidationError extends Error {
 44	  constructor(message: string) {
 45	    super(message);
 46	    this.name = 'MnemonicValidationError';
 47	  }
 48	}
 49	
 50	/**
 51	 * `address_index` fuera del espacio no-hardened `[0, 2^31 - 1]` (HU-06-02 RN-9).
 52	 *
 53	 * Es un error del catálogo (`VALIDATION_ERROR`, HTTP 422) con `details.issues` indicando el
 54	 * parámetro `address_index`: si alcanza la superficie HTTP se serializa con el envelope
 55	 * uniforme de HU-09-05, no como error interno.
 56	 */
 57	export class AddressIndexRangeError extends AppError {
 58	  constructor(message: string) {
 59	    const issues: ValidationIssue[] = [{ field: 'address_index', message }];
 60	    super('VALIDATION_ERROR', message, { issues });
 61	    this.name = 'AddressIndexRangeError';
 62	  }
 63	}
 64	
 65	/**
 66	 * No se pudo hallar un `address_index` con clave BIP-32 válida dentro del rango
 67	 * no-hardened (HU-06-02 RN-8: `I_L >= n` o `k_hijo == 0`, probabilidad ~2^-127).
 68	 */
 69	export class DerivationExhaustedError extends Error {
 70	  constructor(message: string) {
 71	    super(message);
 72	    this.name = 'DerivationExhaustedError';
 73	  }
 74	}
 75	
 76	/**
 77	 * Error interno (NO exportado) que señala la condición de borde de BIP-32 RN-8 en un paso
 78	 * concreto de derivación. Se traduce a `DerivationExhaustedError` en la superficie pública.
 79	 */
 80	class InvalidChildKeyError extends Error {
 81	  constructor(message: string) {
 82	    super(message);
 83	    this.name = 'InvalidChildKeyError';
 84	  }
 85	}
 86	
 87	// ---------------------------------------------------------------------------
 88	// Constantes de dominio
 89	// ---------------------------------------------------------------------------
 90	
 91	/** Offset de los índices hardened de BIP-32: `0x80000000` = 2^31 (HU-06-02 RN-2). */
 92	export const HARDENED_OFFSET = 0x80000000;
 93	
 94	/** Último `address_index` válido del espacio no-hardened: 2^31 - 1 (HU-06-02 RN-9). */
 95	export const MAX_ADDRESS_INDEX = HARDENED_OFFSET - 1;
 96	
 97	/** Entropía fijada por el proyecto: 256 bits => 24 palabras (HU-06-01 RN-1). */
 98	const MNEMONIC_ENTROPY_BITS = 256;
 99	
100	/** Cantidad de palabras exigida por el proyecto (HU-06-01 RN-1/RN-2 (a)). */
101	const MNEMONIC_WORD_COUNT = 24;
102	
103	/** Orden del grupo de secp256k1 (`n`), HU-06-02 RN-1. */
104	const SECP256K1_N: bigint = BigInt(
105	  '0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141'
106	);
107	
108	/** Componentes del path BIP-44 de Ethereum (HU-06-02 RN-2). */
109	const BIP44_PURPOSE = 44;
110	const BIP44_COIN_TYPE_ETHEREUM = 60; // SLIP-44 (00-fundaciones/activos-y-par-de-trading.md)
111	const BIP44_ACCOUNT = 0;
112	const BIP44_CHANGE = 0; // cadena externa, NO hardened
113	
114	/** Clave HMAC de la derivación de la clave maestra BIP-32 (HU-06-02 RN-1). */
115	const BIP32_MASTER_KEY = 'Bitcoin seed';
116	
117	/** Iteraciones y longitud del PBKDF2 de BIP-39 (HU-06-01 RN-3). */
118	const PBKDF2_ITERATIONS = 2048;
119	const SEED_BYTES = 64;
120	
121	// ---------------------------------------------------------------------------
122	// Helpers de bytes / enteros (aritmética exacta con BigInt, nunca floats)
123	// ---------------------------------------------------------------------------
124	
125	const utf8 = (s: string): Uint8Array => new Uint8Array(Buffer.from(s, 'utf8'));
126	
127	function bytesToHex(bytes: Uint8Array): string {
128	  let out = '';
129	  for (let i = 0; i < bytes.length; i++) out += bytes[i].toString(16).padStart(2, '0');
130	  return out;
131	}
132	
133	function bytesToBigIntBE(bytes: Uint8Array): bigint {
134	  let n = 0n;
135	  for (let i = 0; i < bytes.length; i++) n = (n << 8n) | BigInt(bytes[i]);
136	  return n;
137	}
138	
139	/** `ser256(k)`: entero de 256 bits en big-endian, 32 bytes (BIP-32). */
140	function ser256(value: bigint): Uint8Array {
141	  const out = new Uint8Array(32);
142	  let v = value;
143	  for (let i = 31; i >= 0; i--) {
144	    out[i] = Number(v & 0xffn);
145	    v >>= 8n;
146	  }
147	  return out;
148	}
149	
150	/** `ser32(i)`: entero de 32 bits sin signo en big-endian, 4 bytes (BIP-32). */
151	function ser32(index: number): Uint8Array {
152	  const out = new Uint8Array(4);
153	  out[0] = (index >>> 24) & 0xff;
154	  out[1] = (index >>> 16) & 0xff;
155	  out[2] = (index >>> 8) & 0xff;
156	  out[3] = index & 0xff;
157	  return out;
158	}
159	
160	function concatBytes(...parts: Uint8Array[]): Uint8Array {
161	  const total = parts.reduce((acc, p) => acc + p.length, 0);
162	  const out = new Uint8Array(total);
163	  let offset = 0;
164	  for (const p of parts) {
165	    out.set(p, offset);
166	    offset += p.length;
167	  }
168	  return out;
169	}
170	
171	// ---------------------------------------------------------------------------
172	// BIP-39: mnemonic y seed
173	// ---------------------------------------------------------------------------
174	
175	let wordSetCache: Set<string> | null = null;
176	function englishWordSet(): Set<string> {
177	  if (wordSetCache === null) wordSetCache = new Set<string>(ENGLISH_WORDLIST);
178	  return wordSetCache;
179	}
180	
181	/**
182	 * Genera un mnemonic BIP-39 de 24 palabras (256 bits de entropía) usando el CSPRNG del
183	 * sistema (HU-06-01 RN-1). No se registra ni se retorna nada más: el llamador es responsable
184	 * de custodiarlo (RN-5/RN-6).
185	 */
186	export function generateMnemonic24(): string {
187	  return bip39GenerateMnemonic(ENGLISH_WORDLIST, MNEMONIC_ENTROPY_BITS);
188	}
189	
190	/**
191	 * Normaliza el mnemonic a Unicode NFKD y colapsa los espacios en blanco a un único espacio
192	 * simple, recortando extremos (HU-06-01 RN-2). Para el wordlist inglés (ASCII puro) la NFKD
193	 * es un no-op, pero se aplica de forma genérica por conformidad con el estándar y robustez
194	 * ante mnemonics importados de sistemas con otra normalización.
195	 */
196	export function normalizeMnemonic(mnemonic: string): string {
197	  if (typeof mnemonic !== 'string') {
198	    throw new MnemonicValidationError('el mnemonic debe ser una cadena de texto');
199	  }
200	  return mnemonic.normalize('NFKD').trim().replace(/\s+/g, ' ');
201	}
202	
203	/**
204	 * Valida el mnemonic conforme a HU-06-01 RN-2, en este orden:
205	 *   (a) longitud = exactamente 24 palabras (entropía fijada del proyecto: 256 bits);
206	 *   (b) todas las palabras pertenecen al wordlist BIP-39 inglés (2048 palabras);
207	 *   (c) checksum BIP-39 (últimos ENT/32 bits = primeros ENT/32 bits de SHA-256(entropía)).
208	 *
209	 * Lanza `MnemonicValidationError` (equivalente a `VALIDATION_ERROR`) sin incluir el mnemonic
210	 * ni ninguna palabra suya en el mensaje (RN-5).
211	 */
212	export function validateMnemonic24(mnemonic: string): void {
213	  const normalized = normalizeMnemonic(mnemonic);
214	  const words = normalized.length === 0 ? [] : normalized.split(' ');
215	
216	  // (a) longitud
217	  if (words.length !== MNEMONIC_WORD_COUNT) {
218	    throw new MnemonicValidationError(
219	      `mnemonic inválido: se esperaban ${MNEMONIC_WORD_COUNT} palabras (256 bits de entropía) ` +
220	        `y se recibieron ${words.length}`
221	    );
222	  }
223	
224	  // (b) wordlist
225	  const dictionary = englishWordSet();
226	  for (let i = 0; i < words.length; i++) {
227	    if (!dictionary.has(words[i])) {
228	      // Se reporta solo la POSICIÓN, nunca la palabra (custodia RN-5).
229	      throw new MnemonicValidationError(
230	        `mnemonic inválido: la palabra en la posición ${i + 1} no pertenece al wordlist BIP-39 inglés`
231	      );
232	    }
233	  }
234	
235	  // (c) checksum
236	  if (!bip39ValidateMnemonic(normalized, ENGLISH_WORDLIST)) {
237	    throw new MnemonicValidationError('mnemonic inválido: el checksum BIP-39 no verifica');
238	  }
239	}
240	
241	/**
242	 * Deriva la seed binaria de 512 bits (64 bytes) según HU-06-01 RN-3:
243	 * `PBKDF2(HMAC-SHA512, password = mnemonic_NFKD, salt = "mnemonic" + passphrase_NFKD,
244	 *  iteraciones = 2048, dkLen = 64)`.
245	 *
246	 * Función pura y determinista (RN-7). NO valida la longitud del mnemonic: es el algoritmo
247	 * puro de BIP-39, usado también con vectores canónicos de 12 palabras (HU-06-02). La
248	 * validación de provisioning es responsabilidad de `validateMnemonic24`.
249	 */
250	export function mnemonicToSeed(mnemonic: string, passphrase = ''): Buffer {
251	  const password = normalizeMnemonic(mnemonic);
252	  // La passphrase se normaliza NFKD pero NO se colapsan sus espacios: son significativos.
253	  const salt = 'mnemonic' + passphrase.normalize('NFKD');
254	  const derived = noblePbkdf2(sha512, utf8(password), utf8(salt), {
255	    c: PBKDF2_ITERATIONS,
256	    dkLen: SEED_BYTES,
257	  });
258	  return Buffer.from(derived);
259	}
260	
261	// ---------------------------------------------------------------------------
262	// EIP-55 / dirección Ethereum
263	// ---------------------------------------------------------------------------
264	
265	const ADDRESS_RE = /^0x[0-9a-fA-F]{40}$/;
266	
267	/**
268	 * Codifica 20 bytes como dirección Ethereum con checksum EIP-55 (HU-06-02 RN-4).
269	 *
270	 * Acepta `Uint8Array`/`Buffer` de 20 bytes o un string hexadecimal de 40 dígitos, con o sin
271	 * prefijo `0x` y en cualquier caja. El algoritmo computa `Keccak-256` sobre la cadena ASCII
272	 * del hexadecimal en minúsculas (sin `0x`) y pasa a mayúscula el dígito `i` si el nibble `i`
273	 * del hash es >= 8.
274	 */
275	export function toChecksumAddress(address: string | Uint8Array): string {
276	  let lower: string;
277	  if (typeof address === 'string') {
278	    const raw = address.startsWith('0x') || address.startsWith('0X') ? address.slice(2) : address;
279	    if (!/^[0-9a-fA-F]{40}$/.test(raw)) {
280	      throw new Error('dirección inválida: se esperan 40 dígitos hexadecimales (20 bytes)');
281	    }
282	    lower = raw.toLowerCase();
283	  } else {
284	    if (!(address instanceof Uint8Array) || address.length !== 20) {
285	      throw new Error('dirección inválida: se esperan exactamente 20 bytes');
286	    }
287	    lower = bytesToHex(address);
288	  }
289	
290	  const hash = keccak_256(utf8(lower));
291	  let out = '0x';
292	  for (let i = 0; i < lower.length; i++) {
293	    const ch = lower[i];
294	    // nibble i del hash: byte i>>1, mitad alta si i es par.
295	    const nibble = i % 2 === 0 ? hash[i >> 1] >> 4 : hash[i >> 1] & 0x0f;
296	    out += nibble >= 8 ? ch.toUpperCase() : ch;
297	  }
298	  return out;
299	}
300	
301	/**
302	 * `true` si `address` es `0x` + 40 hex con checksum EIP-55 correcto.
303	 *
304	 * Nota deliberada sobre las formas sin caja mixta: una dirección **enteramente en minúsculas**
305	 * o **enteramente en mayúsculas** devuelve `false`, porque no transporta un checksum EIP-55
306	 * verificable (EIP-55 las considera "sin checksum"; que coincidan con la forma canónica sería
307	 * casualidad). Único caso en que esta regla no aplica: direcciones sin ningún dígito
308	 * alfabético (`a`-`f`), donde minúsculas y mayúsculas son la misma cadena y el checksum sí es
309	 * verificable de forma no ambigua; ahí se compara contra la forma canónica.
310	 */
311	export function isValidChecksumAddress(address: string): boolean {
312	  if (typeof address !== 'string' || !ADDRESS_RE.test(address)) return false;
313	  const body = address.slice(2);
314	  const hasCase = body.toLowerCase() !== body.toUpperCase();
315	  if (hasCase && (body === body.toLowerCase() || body === body.toUpperCase())) return false;
316	  return toChecksumAddress(body) === address;
317	}
318	
319	// ---------------------------------------------------------------------------
320	// BIP-32 / BIP-44
321	// ---------------------------------------------------------------------------
322	
323	/**
324	 * Punto de inyección para tests (AT-06-02-08): permite sustituir el HMAC-SHA512 usado por la
325	 * derivación BIP-32 para simular la condición de clave inválida (`I_L >= n` o `k_hijo == 0`,
326	 * probabilidad ~2^-127, no reproducible naturalmente).
327	 */
328	export interface DerivationDeps {
329	  hmacSha512?: (key: Uint8Array, data: Uint8Array) => Uint8Array;
330	}
331	
332	const defaultHmacSha512 = (key: Uint8Array, data: Uint8Array): Uint8Array =>
333	  hmac(sha512, key, data);
334	
335	/** Nodo extendido BIP-32 (privado). Nunca se expone fuera del módulo (RN-6). */
336	interface ExtendedKey {
337	  /** Clave privada como entero; permanece en memoria del módulo. */
338	  readonly k: bigint;
339	  readonly chainCode: Uint8Array;
340	}
341	
342	/** `serP(point(k))`: clave pública comprimida (33 bytes) de la clave privada `k`. */
343	function compressedPublicKey(k: bigint): Uint8Array {
344	  return secp256k1.Point.BASE.multiply(k).toBytes(true);
345	}
346	
347	/** Clave pública sin comprimir sin el prefijo `0x04`: `X || Y` (64 bytes). */
348	function uncompressedXY(k: bigint): Uint8Array {
349	  return secp256k1.Point.BASE.multiply(k).toBytes(false).subarray(1);
350	}
351	
352	/**
353	 * Clave maestra BIP-32 (HU-06-02 RN-1):
354	 * `I = HMAC-SHA512("Bitcoin seed", seed)`, `k = I[0:32]`, `c = I[32:64]`, con `1 <= k < n`.
355	 */
356	function masterKeyFromSeed(seed: Uint8Array, hmacSha512: DerivationDeps['hmacSha512']): ExtendedKey {
357	  if (!(seed instanceof Uint8Array) || seed.length < 16 || seed.length > 64) {
358	    throw new Error('seed inválida: se esperan entre 16 y 64 bytes');
359	  }
360	  const I = (hmacSha512 ?? defaultHmacSha512)(utf8(BIP32_MASTER_KEY), seed);
361	  const k = bytesToBigIntBE(I.subarray(0, 32));
362	  if (k === 0n || k >= SECP256K1_N) {
363	    // BIP-32: seed inutilizable (probabilidad ~2^-127). No se filtra material secreto.
364	    throw new Error('BIP-32: la seed produce una clave maestra inválida (I_L fuera de [1, n-1])');
365	  }
366	  return { k, chainCode: I.subarray(32, 64) };
367	}
368	
369	/**
370	 * `CKDpriv` de BIP-32 (HU-06-02 RN-3):
371	 *  - hardened (`i >= 2^31`): `I = HMAC-SHA512(c_par, 0x00 || ser256(k_par) || ser32(i))`
372	 *  - normal   (`i <  2^31`): `I = HMAC-SHA512(c_par, serP(point(k_par)) || ser32(i))`
373	 *  - `k_hijo = (I_L + k_par) mod n`, `c_hijo = I_R`.
374	 *
375	 * Si `I_L >= n` o `k_hijo == 0`, el índice es inválido (RN-8) y se lanza
376	 * `InvalidChildKeyError` para que el llamador avance al índice siguiente.
377	 */
378	function ckdPriv(
379	  parent: ExtendedKey,
380	  index: number,
381	  hmacSha512: DerivationDeps['hmacSha512']
382	): ExtendedKey {
383	  const data =
384	    index >= HARDENED_OFFSET
385	      ? concatBytes(new Uint8Array([0x00]), ser256(parent.k), ser32(index))
386	      : concatBytes(compressedPublicKey(parent.k), ser32(index));
387	
388	  const I = (hmacSha512 ?? defaultHmacSha512)(parent.chainCode, data);
389	  const IL = bytesToBigIntBE(I.subarray(0, 32));
390	  if (IL >= SECP256K1_N) {
391	    throw new InvalidChildKeyError(`BIP-32: I_L >= n en el índice ${index}`);
392	  }
393	  const k = (IL + parent.k) % SECP256K1_N;
394	  if (k === 0n) {
395	    throw new InvalidChildKeyError(`BIP-32: k_hijo == 0 en el índice ${index}`);
396	  }
397	  return { k, chainCode: I.subarray(32, 64) };
398	}
399	
400	/** Índice hardened: `value + 2^31` (HU-06-02 RN-2). */
401	function hardened(value: number): number {
402	  return value + HARDENED_OFFSET;
403	}
404	
405	/**
406	 * Ruta BIP-44 de Ethereum para un `address_index`: `m/44'/60'/0'/0/${addressIndex}`
407	 * (HU-06-02 RN-2). Los índices efectivos de los componentes hardened son
408	 * 2147483692 (44'), 2147483708 (60') y 2147483648 (0'); `change` y `address_index` son
409	 * no-hardened.
410	 */
411	export function derivationPathFor(addressIndex: number): string {
412	  return `m/${BIP44_PURPOSE}'/${BIP44_COIN_TYPE_ETHEREUM}'/${BIP44_ACCOUNT}'/${BIP44_CHANGE}/${addressIndex}`;
413	}
414	
415	/**
416	 * Nodo `m/44'/60'/0'/0` (la "cadena externa" de la cuenta 0), común a todos los índices.
417	 * Se calcula una sola vez por derivación / barrido de índices.
418	 */
419	function externalChainNode(seed: Uint8Array, hmacSha512: DerivationDeps['hmacSha512']): ExtendedKey {
420	  let node = masterKeyFromSeed(seed, hmacSha512);
421	  const path = [
422	    hardened(BIP44_PURPOSE), // 2147483692
423	    hardened(BIP44_COIN_TYPE_ETHEREUM), // 2147483708
424	    hardened(BIP44_ACCOUNT), // 2147483648
425	    BIP44_CHANGE, // 0 (no hardened)
426	  ];
427	  for (const index of path) node = ckdPriv(node, index, hmacSha512);
428	  return node;
429	}
430	
431	/** Valida el rango no-hardened del `address_index` (HU-06-02 RN-9), ANTES de derivar. */
432	function assertAddressIndexInRange(addressIndex: number): void {
433	  if (
434	    typeof addressIndex !== 'number' ||
435	    !Number.isInteger(addressIndex) ||
436	    addressIndex < 0 ||
437	    addressIndex > MAX_ADDRESS_INDEX
438	  ) {
439	    throw new AddressIndexRangeError(
440	      `address_index inválido: debe ser un entero en [0, ${MAX_ADDRESS_INDEX}] ` +
441	        `(espacio no-hardened de BIP-32); se recibió ${addressIndex}`
442	    );
443	  }
444	}
445	
446	/** Cuenta derivada: solo datos NO secretos (HU-06-02 RN-6). */
447	export interface DerivedAccount {
448	  addressIndex: number;
449	  /** Dirección Ethereum con checksum EIP-55. */
450	  address: string;
451	  /** Path BIP-44 efectivamente usado. */
452	  derivationPath: string;
453	  /** Clave pública comprimida (33 bytes) en hex con prefijo `0x`. Dato NO secreto. */
454	  publicKey: string;
455	}
456	
457	/** Construye el resultado público a partir del nodo hijo (la clave privada no sale de aquí). */
458	function toDerivedAccount(child: ExtendedKey, addressIndex: number): DerivedAccount {
459	  // RN-4: dirección = últimos 20 bytes de Keccak-256(X || Y) con la pública SIN comprimir.
460	  const addressBytes = keccak_256(uncompressedXY(child.k)).subarray(12);
461	  return {
462	    addressIndex,
463	    address: toChecksumAddress(addressBytes),
464	    derivationPath: derivationPathFor(addressIndex),
465	    publicKey: '0x' + bytesToHex(compressedPublicKey(child.k)),
466	  };
467	}
468	
469	/**
470	 * Deriva la cuenta del `address_index` dado sobre `m/44'/60'/0'/0/<addressIndex>`.
471	 *
472	 * Función pura de `(seed, addressIndex)` (HU-06-02 RN-5). Valida el rango
473	 * `[0, 2^31 - 1]` ANTES de derivar (RN-9 => `AddressIndexRangeError`). Nunca expone ni
474	 * logea la clave privada (RN-6).
475	 *
476	 * Si ese índice concreto cae en el borde de BIP-32 (`I_L >= n` o `k_hijo == 0`, RN-8) lanza
477	 * `DerivationExhaustedError`; para avanzar automáticamente al índice siguiente usar
478	 * `deriveAccountFromIndexOrNext`.
479	 */
480	export function deriveAccount(
481	  seed: Uint8Array,
482	  addressIndex: number,
483	  deps?: DerivationDeps
484	): DerivedAccount {
485	  assertAddressIndexInRange(addressIndex);
486	  const hmacSha512 = deps?.hmacSha512;
487	  const parent = externalChainNode(seed, hmacSha512);
488	  try {
489	    return toDerivedAccount(ckdPriv(parent, addressIndex, hmacSha512), addressIndex);
490	  } catch (err) {
491	    if (err instanceof InvalidChildKeyError) {
492	      throw new DerivationExhaustedError(
493	        `el address_index ${addressIndex} produce una clave BIP-32 inválida (RN-8)`
494	      );
495	    }
496	    throw err;
497	  }
498	}
499	
500	/**
501	 * Igual que `deriveAccount`, pero implementa el borde de BIP-32 de HU-06-02 RN-8: si el
502	 * índice produce una clave inválida (`I_L >= n` o `k_hijo == 0`), avanza determinísticamente
503	 * al índice siguiente hasta hallar uno válido. Si se supera `MAX_ADDRESS_INDEX` lanza
504	 * `DerivationExhaustedError`.
505	 *
506	 * El índice efectivamente usado se devuelve en `addressIndex` (y queda reflejado en
507	 * `derivationPath`), consistente con HU-06-03 RN-1.
508	 */
509	export function deriveAccountFromIndexOrNext(
510	  seed: Uint8Array,
511	  startIndex: number,
512	  deps?: DerivationDeps
513	): DerivedAccount {
514	  assertAddressIndexInRange(startIndex);
515	  const hmacSha512 = deps?.hmacSha512;
516	  const parent = externalChainNode(seed, hmacSha512);
517	
518	  for (let index = startIndex; index <= MAX_ADDRESS_INDEX; index++) {
519	    try {
520	      return toDerivedAccount(ckdPriv(parent, index, hmacSha512), index);
521	    } catch (err) {
522	      if (err instanceof InvalidChildKeyError) continue; // RN-8: avanzar al siguiente índice
523	      throw err;
524	    }
525	  }
526	
527	  throw new DerivationExhaustedError(
528	    `no se halló un address_index válido en [${startIndex}, ${MAX_ADDRESS_INDEX}]`
529	  );
530	}

