  1	/**
  2	 * Provisioning y custodia del seed HD (HU-06-01).
  3	 *
  4	 * - El material secreto se persiste **cifrado en reposo** con AES-256-GCM, con nonce
  5	 *   aleatorio de 96 bits por operación de cifrado y tag de 128 bits, en el formato
  6	 *   `nonce || ciphertext || tag` (RN-6).
  7	 * - La clave de cifrado proviene de la configuración del entorno; nunca se persiste junto
  8	 *   al material cifrado ni está embebida en el código.
  9	 * - Ante mnemonic inválido, fallo de descifrado o verificación de integridad fallida, el
 10	 *   proceso **aborta** sin generar ni sobrescribir un seed (RN-11). Esta capa señaliza el
 11	 *   fallo con `ProvisioningError`, que `main.ts` traduce a salida distinta de cero con el
 12	 *   `code` del catálogo en `stderr`, **sin filtrar material secreto** (RN-5).
 13	 */
 14	import { createCipheriv, createDecipheriv, randomBytes } from 'node:crypto';
 15	import { EncryptionKeyFormatError, decodeEncryptionKey } from '../../core/config';
 16	import type { Db } from '../../db/index';
 17	import { transaction } from '../../db/index';
 18	import { nowIso } from '../../core/time';
 19	import {
 20	  MnemonicValidationError,
 21	  deriveAccount,
 22	  generateMnemonic24,
 23	  mnemonicToSeed,
 24	  validateMnemonic24,
 25	} from '../../wallet/hd';
 26	
 27	const NONCE_BYTES = 12;
 28	const TAG_BYTES = 16;
 29	
 30	export type ProvisioningErrorCode = 'VALIDATION_ERROR' | 'INTERNAL_ERROR';
 31	
 32	export class ProvisioningError extends Error {
 33	  constructor(readonly code: ProvisioningErrorCode, message: string) {
 34	    super(message);
 35	    this.name = 'ProvisioningError';
 36	  }
 37	}
 38	
 39	interface SeedPayload {
 40	  v: 1;
 41	  mnemonic: string;
 42	  passphrase: string;
 43	}
 44	
 45	export function encryptPayload(plaintext: Buffer, key: Buffer): Buffer {
 46	  const nonce = randomBytes(NONCE_BYTES);
 47	  const cipher = createCipheriv('aes-256-gcm', key, nonce);
 48	  const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
 49	  const tag = cipher.getAuthTag();
 50	  return Buffer.concat([nonce, ciphertext, tag]);
 51	}
 52	
 53	export function decryptPayload(blob: Buffer, key: Buffer): Buffer {
 54	  if (blob.length < NONCE_BYTES + TAG_BYTES) {
 55	    throw new ProvisioningError('INTERNAL_ERROR', 'El material cifrado del seed está incompleto.');
 56	  }
 57	  const nonce = blob.subarray(0, NONCE_BYTES);
 58	  const tag = blob.subarray(blob.length - TAG_BYTES);
 59	  const ciphertext = blob.subarray(NONCE_BYTES, blob.length - TAG_BYTES);
 60	  const decipher = createDecipheriv('aes-256-gcm', key, nonce);
 61	  decipher.setAuthTag(tag);
 62	  try {
 63	    return Buffer.concat([decipher.update(ciphertext), decipher.final()]);
 64	  } catch {
 65	    // Tag GCM que no verifica: corrupción, restauración incorrecta o credencial errónea.
 66	    throw new ProvisioningError(
 67	      'INTERNAL_ERROR',
 68	      'No se pudo descifrar el seed HD persistido (credencial incorrecta o material corrupto).',
 69	    );
 70	  }
 71	}
 72	
 73	export interface ProvisionedWallet {
 74	  seed: Buffer;
 75	  /** `true` si esta ejecución generó el seed; `false` si lo recuperó del almacenamiento. */
 76	  generated: boolean;
 77	}
 78	
 79	export interface ProvisionOptions {
 80	  db: Db;
 81	  /**
 82	   * Credencial de cifrado **tal como viene del entorno** (sin decodificar). Su ausencia y su
 83	   * formato inválido se clasifican acá y no en la carga de configuración, porque el `code`
 84	   * del aborto depende de si hay un seed persistido (RN-6/RN-11, AT-06-01-11).
 85	   */
 86	  encryptionKeyRaw?: string;
 87	  /** Mnemonic importado por configuración (opcional). Debe cumplir BIP-39 de 24 palabras. */
 88	  importedMnemonic?: string;
 89	  passphrase?: string;
 90	}
 91	
 92	/**
 93	 * Carga el seed persistido o, si no existe, provisiona uno nuevo (o importa el configurado).
 94	 * Nunca regenera ni sobrescribe un seed existente (RN-4/RN-8).
 95	 */
 96	export function provisionWallet(options: ProvisionOptions): ProvisionedWallet {
 97	  const { db } = options;
 98	  const existing = db.prepare('SELECT payload FROM wallet_seed WHERE id = 1').get() as
 99	    | { payload: Uint8Array }
100	    | undefined;
101	
102	  const rawKey = options.encryptionKeyRaw;
103	  let encryptionKey: Buffer | undefined;
104	  let keyProblem: string | undefined;
105	  if (rawKey !== undefined && rawKey.trim() !== '') {
106	    try {
107	      encryptionKey = decodeEncryptionKey(rawKey);
108	    } catch (err) {
109	      if (!(err instanceof EncryptionKeyFormatError)) throw err;
110	      keyProblem = err.message;
111	    }
112	  }
113	
114	  if (!encryptionKey) {
115	    // Credencial ausente **o con formato inválido**: con un seed ya persistido el fallo es
116	    // de descifrado (`INTERNAL_ERROR`, AT-06-01-11); sin seed es un error de configuración
117	    // del entorno (`VALIDATION_ERROR`). En ambos casos se aborta: nunca se continúa sin
118	    // seed ni se genera uno nuevo (RN-11).
119	    const causa = keyProblem
120	      ? 'la credencial de cifrado configurada no tiene un formato válido'
121	      : 'falta la credencial de cifrado (WALLET_ENCRYPTION_KEY)';
122	    throw new ProvisioningError(
123	      existing ? 'INTERNAL_ERROR' : 'VALIDATION_ERROR',
124	      existing
125	        ? `No se pudo descifrar el seed HD persistido: ${causa}.`
126	        : 'La credencial de cifrado del seed HD se provee por configuración del entorno y ' +
127	          `nunca se embebe en el código (HU-06-01 RN-6): ${causa}. ` +
128	          (keyProblem ?? 'Generá una con: npm run genkey'),
129	    );
130	  }
131	
132	  if (existing) {
133	    const plaintext = decryptPayload(Buffer.from(existing.payload), encryptionKey);
134	    let payload: SeedPayload;
135	    try {
136	      payload = JSON.parse(plaintext.toString('utf8')) as SeedPayload;
137	    } catch {
138	      throw new ProvisioningError('INTERNAL_ERROR', 'El seed HD persistido no es legible.');
139	    }
140	    if (typeof payload?.mnemonic !== 'string') {
141	      throw new ProvisioningError('INTERNAL_ERROR', 'El seed HD persistido no es legible.');
142	    }
143	    const seed = mnemonicToSeed(payload.mnemonic, payload.passphrase ?? '');
144	    return { seed, generated: false };
145	  }
146	
147	  const passphrase = options.passphrase ?? '';
148	  let mnemonic: string;
149	  if (options.importedMnemonic) {
150	    try {
151	      validateMnemonic24(options.importedMnemonic);
152	    } catch (err) {
153	      if (err instanceof MnemonicValidationError) {
154	        // No se adopta ni se persiste nada (RN-2/RN-11).
155	        throw new ProvisioningError('VALIDATION_ERROR', `Mnemonic BIP-39 inválido: ${err.message}`);
156	      }
157	      throw err;
158	    }
159	    mnemonic = options.importedMnemonic;
160	  } else {
161	    mnemonic = generateMnemonic24();
162	  }
163	
164	  const payload: SeedPayload = { v: 1, mnemonic, passphrase };
165	  const blob = encryptPayload(Buffer.from(JSON.stringify(payload), 'utf8'), encryptionKey);
166	  // Escritura atómica: una única transacción; el seed se considera provisionado sólo si
167	  // luego puede leerse y descifrarse (RN-9).
168	  transaction(db, () => {
169	    db.prepare('INSERT INTO wallet_seed (id, payload, created_at) VALUES (1, ?, ?)').run(
170	      blob,
171	      nowIso(),
172	    );
173	  });
174	  const verification = db.prepare('SELECT payload FROM wallet_seed WHERE id = 1').get() as
175	    | { payload: Uint8Array }
176	    | undefined;
177	  if (!verification) {
178	    throw new ProvisioningError('INTERNAL_ERROR', 'El seed HD no quedó persistido.');
179	  }
180	  decryptPayload(Buffer.from(verification.payload), encryptionKey);
181	
182	  return { seed: mnemonicToSeed(mnemonic, passphrase), generated: true };
183	}
184	
185	/**
186	 * Smoke test de integridad al arrancar (RN-10): con un mapeo `cuenta → address_index` no
187	 * vacío, se re-deriva el índice más bajo asignado y se compara con la dirección
188	 * persistida. Cualquier discrepancia aborta el arranque (RN-11).
189	 */
190	export function verifySeedIntegrity(db: Db, seed: Buffer, k = 1): void {
191	  const rows = db
192	    .prepare(
193	      'SELECT address_index AS addressIndex, address FROM deposit_addresses ORDER BY address_index ASC LIMIT ?',
194	    )
195	    .all(k) as unknown as { addressIndex: number; address: string }[];
196	  for (const row of rows) {
197	    const derived = deriveAccount(seed, row.addressIndex);
198	    if (derived.address !== row.address) {
199	      throw new ProvisioningError(
200	        'INTERNAL_ERROR',
201	        `Verificación de integridad del seed fallida para el índice ${row.addressIndex}: ` +
202	          'la dirección derivada no coincide con la persistida.',
203	      );
204	    }
205	  }
206	}

