  1	/**
  2	 * Asignación y consulta de direcciones de depósito (HU-06-03, HU-06-04).
  3	 *
  4	 * Biyección cuenta ↔ `address_index` ↔ dirección: el índice es único, monótono creciente
  5	 * desde 0, sin reúso e inmutable (INV-EPICA-06-A). La única fuente de huecos admitida es un
  6	 * índice que produzca una clave BIP-32 inválida (~2⁻¹²⁷), que se salta de forma
  7	 * determinista y queda auditado en `derivation_skips` (HU-06-03 RN-1 / HU-06-02 RN-8).
  8	 */
  9	import { EventEmitter } from 'node:events';
 10	import { AppError } from '../../core/errors';
 11	import { CHAIN_ID, NETWORK_NAME } from '../../core/config';
 12	import { nowIso } from '../../core/time';
 13	import { isUniqueConstraintError, transaction, type Db } from '../../db/index';
 14	import { MAX_ADDRESS_INDEX, deriveAccountFromIndexOrNext } from '../../wallet/hd';
 15	
 16	export interface DepositAddressRecord {
 17	  accountId: string;
 18	  addressIndex: number;
 19	  address: string;
 20	  derivationPath: string;
 21	  network: string;
 22	  chainId: string;
 23	  createdAt: string;
 24	}
 25	
 26	export interface DepositAddressAssignedEvent {
 27	  accountId: string;
 28	  addressIndex: number;
 29	  address: string;
 30	  chainId: string;
 31	}
 32	
 33	export const DEPOSIT_ADDRESS_ASSIGNED = 'DepositAddressAssigned';
 34	
 35	export class WalletService {
 36	  readonly events = new EventEmitter();
 37	  private pendingEvents: DepositAddressAssignedEvent[] = [];
 38	
 39	  constructor(private readonly db: Db, private readonly seed: Buffer) {}
 40	
 41	  find(accountId: string): DepositAddressRecord | undefined {
 42	    return this.db
 43	      .prepare(
 44	        `SELECT account_id AS accountId, address_index AS addressIndex, address,
 45	                derivation_path AS derivationPath, network, chain_id AS chainId,
 46	                created_at AS createdAt
 47	         FROM deposit_addresses WHERE account_id = ?`,
 48	      )
 49	      .get(accountId) as DepositAddressRecord | undefined;
 50	  }
 51	
 52	  listAll(): DepositAddressRecord[] {
 53	    return this.db
 54	      .prepare(
 55	        `SELECT account_id AS accountId, address_index AS addressIndex, address,
 56	                derivation_path AS derivationPath, network, chain_id AS chainId,
 57	                created_at AS createdAt
 58	         FROM deposit_addresses ORDER BY address_index ASC`,
 59	      )
 60	      .all() as unknown as DepositAddressRecord[];
 61	  }
 62	
 63	  /**
 64	   * Asigna la dirección de la cuenta **dentro de una transacción ya abierta** (alta de
 65	   * cuenta, HU-06-03 RN-12). Es idempotente: si la cuenta ya tiene índice, no hace nada.
 66	   */
 67	  assignForAccountInTransaction(accountId: string): DepositAddressRecord {
 68	    const existing = this.find(accountId);
 69	    if (existing) return existing;
 70	
 71	    // RN-10: sólo se asigna dirección a una cuenta existente. Se verifica **antes** de
 72	    // derivar y de tocar el contador de índices, de modo que una referencia inválida no
 73	    // consume un índice ni produce una dirección (AT-06-03-08).
 74	    const account = this.db
 75	      .prepare('SELECT 1 AS present FROM accounts WHERE account_id = ?')
 76	      .get(accountId) as { present: number } | undefined;
 77	    if (!account) {
 78	      throw new AppError('ACCOUNT_NOT_FOUND', 'La cuenta referenciada no existe.', { accountId });
 79	    }
 80	
 81	    const row = this.db
 82	      .prepare('SELECT MAX(address_index) AS maxIndex FROM deposit_addresses')
 83	      .get() as { maxIndex: number | null };
 84	    const startIndex = row.maxIndex === null ? 0 : row.maxIndex + 1;
 85	    if (startIndex > MAX_ADDRESS_INDEX) {
 86	      // HU-06-03 RN-13: nunca se produce silenciosamente un índice hardened.
 87	      throw new AppError(
 88	        'INTERNAL_ERROR',
 89	        'Se agotó el espacio de índices de derivación no-hardened.',
 90	      );
 91	    }
 92	
 93	    const derived = deriveAccountFromIndexOrNext(this.seed, startIndex);
 94	    // Auditoría de índices saltados por clave BIP-32 inválida (RN-1).
 95	    for (let skipped = startIndex; skipped < derived.addressIndex; skipped += 1) {
 96	      this.db
 97	        .prepare(
 98	          'INSERT OR IGNORE INTO derivation_skips (address_index, reason, created_at) VALUES (?, ?, ?)',
 99	        )
100	        .run(skipped, 'INVALID_BIP32_KEY', nowIso());
101	    }
102	
103	    const record: DepositAddressRecord = {
104	      accountId,
105	      addressIndex: derived.addressIndex,
106	      address: derived.address,
107	      derivationPath: derived.derivationPath,
108	      network: NETWORK_NAME,
109	      chainId: CHAIN_ID,
110	      createdAt: nowIso(),
111	    };
112	    this.db
113	      .prepare(
114	        `INSERT INTO deposit_addresses
115	           (account_id, address_index, address, derivation_path, network, chain_id, created_at)
116	         VALUES (?, ?, ?, ?, ?, ?, ?)`,
117	      )
118	      .run(
119	        record.accountId,
120	        record.addressIndex,
121	        record.address,
122	        record.derivationPath,
123	        record.network,
124	        record.chainId,
125	        record.createdAt,
126	      );
127	
128	    const event: DepositAddressAssignedEvent = {
129	      accountId: record.accountId,
130	      addressIndex: record.addressIndex,
131	      address: record.address,
132	      chainId: record.chainId,
133	    };
134	    // El evento de dominio se persiste dentro de la misma transacción (queda disponible
135	    // para la épica 07 aunque el proceso caiga inmediatamente después) y se publica
136	    // in-process recién tras el commit.
137	    this.db
138	      .prepare('INSERT INTO domain_events (type, payload, created_at) VALUES (?, ?, ?)')
139	      .run(DEPOSIT_ADDRESS_ASSIGNED, JSON.stringify(event), record.createdAt);
140	    this.pendingEvents.push(event);
141	    return record;
142	  }
143	
144	  /** Publica los eventos encolados por asignaciones ya committeadas (HU-06-03 RN-11). */
145	  publishPendingEvents(): void {
146	    const events = this.pendingEvents;
147	    this.pendingEvents = [];
148	    for (const event of events) {
149	      this.events.emit(DEPOSIT_ADDRESS_ASSIGNED, event);
150	    }
151	  }
152	
153	  /**
154	   * Fallback idempotente de HU-06-04 RN-5: devuelve la dirección de la cuenta y, si no
155	   * existiera, la asigna. Nunca asigna un segundo índice a una cuenta que ya tiene uno.
156	   */
157	  getOrAssign(accountId: string): DepositAddressRecord {
158	    const existing = this.find(accountId);
159	    if (existing) return existing;
160	    let record: DepositAddressRecord;
161	    try {
162	      record = transaction(this.db, () => this.assignForAccountInTransaction(accountId));
163	    } catch (err) {
164	      if (isUniqueConstraintError(err)) {
165	        // Otra asignación concurrente ganó la carrera: se devuelve la ya persistida.
166	        const winner = this.find(accountId);
167	        if (winner) return winner;
168	      }
169	      throw err;
170	    }
171	    this.publishPendingEvents();
172	    return record;
173	  }
174	
175	  /** Eventos de dominio persistidos (inspección interna / épica 07 al arrancar). */
176	  listEvents(type = DEPOSIT_ADDRESS_ASSIGNED): DepositAddressAssignedEvent[] {
177	    const rows = this.db
178	      .prepare('SELECT payload FROM domain_events WHERE type = ? ORDER BY id ASC')
179	      .all(type) as unknown as { payload: string }[];
180	    return rows.map((r) => JSON.parse(r.payload) as DepositAddressAssignedEvent);
181	  }
182	}

