    16	  accounts: AccountService;
    17	  sessions: SessionService;
    18	  wallet: WalletService;
    19	  audit: AuditLog;
    20	}
    21	
    22	export interface BootstrappedApp {
    23	  app: FastifyInstance;
    24	  db: Db;
    25	  services: Services;
    26	  seed: Buffer;
    27	  close(): Promise<void>;
    28	}
    29	
    30	export function createServices(config: Config, db: Db, seed: Buffer): Services {
    31	  // El eco por `stderr` del log de auditoría se silencia sólo cuando el logging está
    32	  // apagado (entorno de tests); la persistencia del log ocurre siempre (RNE-9).
    33	  const audit = new AuditLog(db, config.logLevel !== 'silent');
    34	  const sessions = new SessionService(db, config.sessionTtlSeconds);
    35	  const wallet = new WalletService(db, seed);
    36	  const accounts = new AccountService(db, sessions, audit, wallet);
    37	  return { accounts, sessions, wallet, audit };
    38	}
    39	
    40	export function bootstrap(config: Config): BootstrappedApp {
    41	  const db = openDatabase(config.databasePath);
    42	  const provisioned = provisionWallet({
    43	    db,
    44	    encryptionKeyRaw: config.walletEncryptionKeyRaw,
    45	    importedMnemonic: config.walletMnemonic,
    46	    passphrase: config.walletMnemonicPassphrase,
    47	  });
    48	  // Smoke test de integridad del seed contra el mapeo persistido (HU-06-01 RN-10).
    49	  verifySeedIntegrity(db, provisioned.seed);
    50	  const services = createServices(config, db, provisioned.seed);
    51	  const app = buildApp({ config, db, ...services });
    52	  return {
    53	    app,
    54	    db,
    55	    services,
    56	    seed: provisioned.seed,
    57	    async close() {
    58	      await app.close();
    59	      db.close();
    60	    },
    61	  };
    62	}
===== MAIN =====
     1	/**
     2	 * Punto de entrada del backend.
     3	 *
     4	 * Secuencia de arranque:
     5	 *  1. Carga y validación de configuración (TTL de sesión, credencial de cifrado, red).
     6	 *  2. Apertura de la base persistente.
     7	 *  3. Provisioning/carga del seed HD y **smoke test de integridad** (HU-06-01 RN-10).
     8	 *  4. Verificación opcional del endpoint JSON-RPC configurado (chainId 11155111).
     9	 *  5. Levantado del servidor HTTP.
    10	 *
    11	 * Cualquier fallo de (1)–(3) **aborta** con código de salida distinto de cero y el `code`
    12	 * del catálogo en `stderr`, sin filtrar material secreto (HU-06-01 RN-11).
    13	 */
    14	import { ConfigError, loadConfig, CHAIN_ID } from './core/config';
    15	import { warmUpDummyHash } from './core/password';
    16	import { ProvisioningError } from './modules/wallet/seedStore';
    17	import { JsonRpcClient } from './chain/rpc';
    18	import { bootstrap, type BootstrappedApp } from './bootstrap';
    19	
    20	function abort(code: string, message: string): never {
    21	  process.stderr.write(`${JSON.stringify({ fatal: { code, message } })}\n`);
    22	  process.exit(1);
    23	}
    24	
    25	async function main(): Promise<void> {
    26	  let config;
    27	  try {
    28	    config = loadConfig();
    29	  } catch (err) {
    30	    if (err instanceof ConfigError) abort('VALIDATION_ERROR', err.message);
    31	    throw err;
    32	  }
    33	
    34	  let booted: BootstrappedApp;
    35	  try {
    36	    booted = bootstrap(config);
    37	  } catch (err) {
    38	    if (err instanceof ProvisioningError) abort(err.code, err.message);
    39	    throw err;
    40	  }
    41	
    42	  const rpc = new JsonRpcClient(config.ethRpcUrl);
    43	  if (rpc.configured) {
    44	    try {
    45	      const chainId = await rpc.chainId();
    46	      if (chainId !== CHAIN_ID) {
    47	        abort(
    48	          'CHAIN_ID_MISMATCH',
    49	          `El endpoint JSON-RPC configurado reporta chainId ${chainId}; se esperaba ${CHAIN_ID}.`,
    50	        );
    51	      }
    52	      process.stdout.write(`JSON-RPC verificado: chainId ${chainId} (sepolia).\n`);
    53	    } catch (err) {
    54	      if (err instanceof Error && err.name === 'ProvisioningError') throw err;
    55	      process.stderr.write(
    56	        `Aviso: no se pudo contactar el endpoint JSON-RPC configurado (${(err as Error).message}). ` +
    57	          'El backend arranca igual: esta etapa no ejecuta operaciones on-chain.\n',
    58	      );
    59	    }
    60	  }
    61	
    62	  await warmUpDummyHash();
    63	
    64	  await booted.app.listen({ host: config.host, port: config.port });
    65	
    66	  const shutdown = async (): Promise<void> => {
    67	    await booted.close();
    68	    process.exit(0);
    69	  };
    70	  process.on('SIGINT', () => void shutdown());
    71	  process.on('SIGTERM', () => void shutdown());
    72	}
    73	
    74	void main().catch((err) => {
    75	  process.stderr.write(`${JSON.stringify({ fatal: { code: 'INTERNAL_ERROR', message: (err as Error).message } })}\n`);
    76	  process.exit(1);
    77	});
===== AUDIT =====
     1	/**
     2	 * Log de auditoría interno de eventos de autenticación (RNE-9).
     3	 *
     4	 * Es **interno**: no se expone por la API del usuario final, por lo que su existencia no
     5	 * viola la regla de no-enumeración de cuentas (RNE-3). Se persiste en la base y además se
     6	 * emite por `stderr` en formato JSON para inspección operativa. Nunca registra la
     7	 * contraseña, su hash, ni el token emitido (RNE-2 / HU-09-02 RN-11).
     8	 */
     9	import type { Db } from '../db/index';
    10	import { nowIso } from './time';
    11	
    12	export type AuditEvent = 'REGISTER' | 'LOGIN';
    13	export type AuditResult = 'SUCCESS' | 'FAILURE';
    14	
    15	export interface AuditRecord {
    16	  timestamp: string;
    17	  event: AuditEvent;
    18	  email: string | null;
    19	  result: AuditResult;
    20	  reason?: string | null;
    21	  origin?: string | null;
    22	}
    23	
    24	export class AuditLog {
    25	  constructor(private readonly db: Db, private readonly echoToStderr = true) {}
    26	
    27	  record(entry: Omit<AuditRecord, 'timestamp'> & { timestamp?: string }): void {
    28	    const timestamp = entry.timestamp ?? nowIso();
    29	    this.db
    30	      .prepare(
    31	        'INSERT INTO auth_audit_log (timestamp, event, email, result, reason, origin) VALUES (?, ?, ?, ?, ?, ?)',
    32	      )
    33	      .run(
    34	        timestamp,
    35	        entry.event,
    36	        entry.email,
    37	        entry.result,
    38	        entry.reason ?? null,
    39	        entry.origin ?? null,
    40	      );
    41	    if (this.echoToStderr) {
    42	      process.stderr.write(
    43	        JSON.stringify({ audit: { ...entry, timestamp } }) + '\n',
    44	      );
    45	    }
    46	  }
    47	
    48	  /** Sólo para inspección interna / tests (no hay superficie HTTP para esto). */
    49	  list(limit = 100): AuditRecord[] {
    50	    return this.db
    51	      .prepare('SELECT timestamp, event, email, result, reason, origin FROM auth_audit_log ORDER BY id DESC LIMIT ?')
    52	      .all(limit) as unknown as AuditRecord[];
    53	  }
    54	}

