  1	/**
  2	 * Configuración del backend, leída del entorno y validada al arranque.
  3	 *
  4	 * Una configuración inválida **impide el arranque** (no se inicia el servicio en estado
  5	 * inválido): HU-01-02 RN-3 (rango del TTL) y HU-06-01 RN-6/RN-11 (credencial de cifrado).
  6	 */
  7	import * as fs from 'node:fs';
  8	import * as path from 'node:path';
  9	import { isValidChecksumAddress, toChecksumAddress } from '../wallet/hd';
 10	
 11	/** Red única del proyecto: Sepolia (spec/00-fundaciones/activos-y-par-de-trading.md §1). */
 12	export const CHAIN_ID = '11155111';
 13	export const NETWORK_NAME = 'sepolia';
 14	/** Confirmaciones requeridas (constante fundacional; la consumen las épicas 07/08). */
 15	export const CONFIRMACIONES_REQUERIDAS = 12;
 16	
 17	export class ConfigError extends Error {}
 18	
 19	export interface RateLimitPolicy {
 20	  enabled: boolean;
 21	  max: number;
 22	  windowSeconds: number;
 23	}
 24	
 25	export interface Config {
 26	  host: string;
 27	  port: number;
 28	  databasePath: string;
 29	  /** TTL del token de sesión en segundos; entero en [60, 86400] (HU-01-02 RN-3). */
 30	  sessionTtlSeconds: number;
 31	  /**
 32	   * Credencial de cifrado del seed **tal como viene del entorno**, sin decodificar
 33	   * (HU-06-01 RN-6). Ni su ausencia ni su formato inválido se resuelven acá: ambos casos
 34	   * los decide el provisioning, que es el único punto donde se distingue "no hay seed
 35	   * todavía" (`VALIDATION_ERROR`) de "hay un seed persistido que no se puede descifrar"
 36	   * (`INTERNAL_ERROR`, AT-06-01-11) — la credencial ausente **o incorrecta** sobre un seed
 37	   * ya persistido aborta siempre con `INTERNAL_ERROR`.
 38	   */
 39	  walletEncryptionKeyRaw?: string;
 40	  /** Mnemonic importado por configuración (opcional); si falta, se genera uno nuevo. */
 41	  walletMnemonic?: string;
 42	  walletMnemonicPassphrase: string;
 43	  /** Dirección del contrato USDC-mock del entorno (checksum EIP-55). */
 44	  usdcContractAddress: string;
 45	  /** Endpoint JSON-RPC de Sepolia (opcional en esta etapa; sin default de terceros). */
 46	  ethRpcUrl: string;
 47	  /** Rate limit por cuenta y endpoint para endpoints autenticados (HU-09-02 RN-12). */
 48	  apiRateLimit: RateLimitPolicy;
 49	  /** Anti-flood del registro (HU-01-01 RN-10); desactivado salvo configuración explícita. */
 50	  registerRateLimit: RateLimitPolicy;
 51	  /** Anti-fuerza-bruta del login sobre intentos fallidos (HU-01-02 RN-9). */
 52	  loginRateLimit: RateLimitPolicy;
 53	  /** Token para las rutas internas (`/internal/*`); si falta, sólo se admite loopback. */
 54	  internalApiToken?: string;
 55	  /**
 56	   * Orígenes exactos habilitados para CORS (`CORS_ALLOWED_ORIGINS`). Lista **vacía** =
 57	   * CORS deshabilitado (el backend no emite ningún header de CORS), que es el default.
 58	   * La spec no define CORS; es soporte de despliegue para el cliente web de la épica 10,
 59	   * que corre en otro origen (`http://localhost:5173` en desarrollo).
 60	   */
 61	  corsAllowedOrigins: string[];
 62	  logLevel: string;
 63	}
 64	
 65	function readEnvFile(file: string): void {
 66	  if (!fs.existsSync(file)) return;
 67	  const content = fs.readFileSync(file, 'utf8');
 68	  for (const rawLine of content.split(/\r?\n/)) {
 69	    const line = rawLine.trim();
 70	    if (!line || line.startsWith('#')) continue;
 71	    const eq = line.indexOf('=');
 72	    if (eq === -1) continue;
 73	    const key = line.slice(0, eq).trim();
 74	    let value = line.slice(eq + 1).trim();
 75	    if (
 76	      (value.startsWith('"') && value.endsWith('"') && value.length >= 2) ||
 77	      (value.startsWith("'") && value.endsWith("'") && value.length >= 2)
 78	    ) {
 79	      value = value.slice(1, -1);
 80	    }
 81	    if (process.env[key] === undefined) process.env[key] = value;
 82	  }
 83	}
 84	
 85	function parseIntStrict(value: string, name: string): number {
 86	  if (!/^-?\d+$/.test(value.trim())) {
 87	    throw new ConfigError(`${name} debe ser un entero; se recibió "${value}".`);
 88	  }
 89	  return Number.parseInt(value.trim(), 10);
 90	}
 91	
 92	function parseBool(value: string | undefined, fallback: boolean): boolean {
 93	  if (value === undefined || value.trim() === '') return fallback;
 94	  const v = value.trim().toLowerCase();
 95	  if (['1', 'true', 'yes', 'on'].includes(v)) return true;
 96	  if (['0', 'false', 'no', 'off'].includes(v)) return false;
 97	  throw new ConfigError(`Valor booleano inválido: "${value}".`);
 98	}
 99	
100	/** Credencial de cifrado con formato/longitud inválidos (la clasifica el provisioning). */
101	export class EncryptionKeyFormatError extends Error {
102	  constructor(message: string) {
103	    super(message);
104	    this.name = 'EncryptionKeyFormatError';
105	  }
106	}
107	
108	/**
109	 * Decodifica la credencial AES-256-GCM del entorno (64 hex, con o sin `0x`, o base64 de 32
110	 * bytes). El mensaje de error nunca incluye el valor recibido (HU-06-01 RN-5).
111	 */
112	export function decodeEncryptionKey(raw: string): Buffer {
113	  const value = raw.trim();
114	  let buf: Buffer;
115	  if (/^(0x)?[0-9a-fA-F]{64}$/.test(value)) {
116	    buf = Buffer.from(value.replace(/^0x/, ''), 'hex');
117	  } else {
118	    buf = Buffer.from(value, 'base64');
119	  }
120	  if (buf.length !== 32) {
121	    throw new EncryptionKeyFormatError(
122	      'WALLET_ENCRYPTION_KEY debe ser una clave de 32 bytes (64 hex o 44 caracteres base64). ' +
123	        'Podés generar una con: npm run genkey',
124	    );
125	  }
126	  return buf;
127	}
128	
129	function rateLimitFrom(
130	  env: NodeJS.ProcessEnv,
131	  enabledVar: string,
132	  maxVar: string,
133	  windowVar: string,
134	  defaults: RateLimitPolicy,
135	  /**
136	   * `true` para las políticas **opcionales** de la épica 01: cuando se activan, umbral y
137	   * ventana son obligatorios y deben estar declarados en el entorno (HU-01-01 RN-10,
138	   * HU-01-02 RN-9); activarlas sin declararlos impide el arranque en vez de caer en
139	   * defaults silenciosos. `false` para el límite de HU-09-02 RN-12, cuyos parámetros
140	   * (60 req / 60 s por cuenta y endpoint) los fija la propia spec.
141	   */
142	  parametersRequiredWhenEnabled: boolean,
143	): RateLimitPolicy {
144	  const enabled = parseBool(env[enabledVar], defaults.enabled);
145	  if (!enabled) return { enabled: false, max: defaults.max, windowSeconds: defaults.windowSeconds };
146	  const rawMax = env[maxVar];
147	  const rawWindow = env[windowVar];
148	  const declaredMax = rawMax !== undefined && rawMax.trim() !== '';
149	  const declaredWindow = rawWindow !== undefined && rawWindow.trim() !== '';
150	  if (parametersRequiredWhenEnabled && (!declaredMax || !declaredWindow)) {
151	    const faltantes = [!declaredMax ? maxVar : null, !declaredWindow ? windowVar : null]
152	      .filter((name): name is string => name !== null)
153	      .join(' y ');
154	    throw new ConfigError(
155	      `Con ${enabledVar}=true, el umbral y la ventana del rate limiting son obligatorios y ` +
156	        `deben estar declarados en el entorno; falta declarar ${faltantes}.`,
157	    );
158	  }
159	  const max = declaredMax ? parseIntStrict(rawMax as string, maxVar) : defaults.max;
160	  const windowSeconds = declaredWindow
161	    ? parseIntStrict(rawWindow as string, windowVar)
162	    : defaults.windowSeconds;
163	  if (max <= 0) throw new ConfigError(`${maxVar} debe ser un entero positivo.`);
164	  if (windowSeconds <= 0) throw new ConfigError(`${windowVar} debe ser un entero positivo.`);
165	  return { enabled: true, max, windowSeconds };
166	}
167	
168	/**
169	 * Normaliza la dirección del contrato USDC del entorno a `0x` + 40 hex con checksum EIP-55
170	 * (HU-09-01 RN-10 / HU-06-04 RN-6): es el valor que se emite como `tokenAddress`.
171	 *
172	 * - Formato inválido (no son 40 hex con prefijo `0x`) ⇒ no se arranca.
173	 * - Caja mixta ⇒ debe traer un checksum EIP-55 correcto; si no coincide, se trata como
174	 *   error de tipeo y no se arranca.
175	 * - Toda en minúsculas o toda en mayúsculas (formas "sin checksum" según EIP-55) ⇒ se
176	 *   normaliza a la forma con checksum.
177	 */
178	export function normalizeContractAddress(raw: string, name: string): string {
179	  const value = raw.trim();
180	  if (!/^0x[0-9a-fA-F]{40}$/.test(value)) {
181	    throw new ConfigError(
182	      `${name} debe ser una dirección Ethereum: "0x" seguido de 40 dígitos hexadecimales; ` +
183	        `se recibió "${value}".`,
184	    );
185	  }
186	  const body = value.slice(2);
187	  const hasMixedCase = body !== body.toLowerCase() && body !== body.toUpperCase();
188	  if (hasMixedCase && !isValidChecksumAddress(value)) {
189	    throw new ConfigError(
190	      `${name} tiene caja mixta pero su checksum EIP-55 no verifica; ` +
191	        `la forma correcta de esa dirección es ${toChecksumAddress(value)}.`,
192	    );
193	  }
194	  return toChecksumAddress(value);
195	}
196	
197	/**
198	 * Parsea `CORS_ALLOWED_ORIGINS`: lista separada por comas de orígenes **exactos**
199	 * (`esquema://host[:puerto]`), p. ej. `http://localhost:5173,http://127.0.0.1:5173`.
200	 *
201	 * Vacía o ausente ⇒ lista vacía ⇒ CORS deshabilitado. Un origen mal formado (con path,
202	 * query, fragmento, credenciales, esquema no HTTP(S), o el comodín `*`) **impide el
203	 * arranque**, con el mismo mecanismo que el resto de las validaciones de configuración.
204	 * Se tolera una barra final (`http://host:5173/`) y se normaliza.
205	 */
206	export function parseCorsAllowedOrigins(raw: string | undefined): string[] {
207	  if (raw === undefined || raw.trim() === '') return [];
208	  const origins: string[] = [];
209	  for (const part of raw.split(',')) {
210	    const value = part.trim().replace(/\/$/, '');
211	    if (value === '') continue;
212	    if (value === '*') {
213	      throw new ConfigError(
214	        'CORS_ALLOWED_ORIGINS no admite el comodín "*": hay que listar orígenes exactos.',
215	      );
216	    }
217	    let url: URL;
218	    try {
219	      url = new URL(value);
220	    } catch {
221	      throw new ConfigError(
222	        `CORS_ALLOWED_ORIGINS debe listar orígenes con la forma "esquema://host[:puerto]"; ` +
223	          `se recibió "${value}".`,
224	      );
225	    }
226	    const wellFormed =
227	      (url.protocol === 'http:' || url.protocol === 'https:') &&
228	      url.username === '' &&
229	      url.password === '' &&
230	      url.search === '' &&
231	      url.hash === '' &&
232	      (url.pathname === '' || url.pathname === '/') &&
233	      url.origin === value;
234	    if (!wellFormed) {
235	      throw new ConfigError(
236	        `CORS_ALLOWED_ORIGINS debe listar orígenes exactos "esquema://host[:puerto]" (http o ` +
237	          `https, sin path, query, fragmento ni credenciales); se recibió "${value}".`,
238	      );
239	    }
240	    if (!origins.includes(url.origin)) origins.push(url.origin);
241	  }
242	  return origins;
243	}
244	
245	/**
246	 * Dirección por defecto del USDC-mock en Sepolia. Es un parámetro del despliegue
247	 * (spec/00-fundaciones/activos-y-par-de-trading.md §2.2): se sobreescribe con
248	 * `USDC_CONTRACT_ADDRESS`.
249	 */
250	export const DEFAULT_USDC_CONTRACT_ADDRESS = '0x1c7D4B196Cb0C7B01d743Fbc6116a902379C7238';
251	
252	export function loadConfig(env: NodeJS.ProcessEnv = process.env): Config {
253	  if (parseBool(env.LOAD_DOTENV, true)) {
254	    readEnvFile(path.resolve(process.cwd(), '.env'));
255	  }
256	
257	  const port = env.PORT ? parseIntStrict(env.PORT, 'PORT') : 3000;
258	  if (port < 0 || port > 65535) throw new ConfigError('PORT fuera de rango.');
259	
260	  const sessionTtlSeconds = env.SESSION_TTL_SECONDS
261	    ? parseIntStrict(env.SESSION_TTL_SECONDS, 'SESSION_TTL_SECONDS')
262	    : 3600;
263	  // HU-01-02 RN-3: TTL entero positivo en [60, 86400]; fuera de rango => no se arranca.
264	  if (sessionTtlSeconds < 60 || sessionTtlSeconds > 86400) {
265	    throw new ConfigError(
266	      `SESSION_TTL_SECONDS debe ser un entero en el rango [60, 86400]; se recibió ${sessionTtlSeconds}.`,
267	    );
268	  }
269	
270	  const chainIdEnv = (env.CHAIN_ID ?? CHAIN_ID).trim();
271	  if (chainIdEnv !== CHAIN_ID) {
272	    throw new ConfigError(
273	      `La única red soportada es Sepolia (chainId ${CHAIN_ID}); se configuró ${chainIdEnv}.`,
274	    );
275	  }
276	
277	  return {
278	    host: env.HOST?.trim() || '0.0.0.0',
279	    port,
280	    databasePath: env.DATABASE_PATH?.trim() || path.resolve(process.cwd(), 'data', 'exchange.db'),
281	    sessionTtlSeconds,
282	    walletEncryptionKeyRaw: env.WALLET_ENCRYPTION_KEY,
283	    walletMnemonic: env.WALLET_MNEMONIC?.trim() ? env.WALLET_MNEMONIC.trim() : undefined,
284	    walletMnemonicPassphrase: env.WALLET_MNEMONIC_PASSPHRASE ?? '',
285	    usdcContractAddress: normalizeContractAddress(
286	      env.USDC_CONTRACT_ADDRESS?.trim() || DEFAULT_USDC_CONTRACT_ADDRESS,
287	      'USDC_CONTRACT_ADDRESS',
288	    ),
289	    ethRpcUrl: env.ETH_RPC_URL?.trim() || '',
290	    apiRateLimit: rateLimitFrom(
291	      env,
292	      'API_RATE_LIMIT_ENABLED',
293	      'API_RATE_LIMIT_MAX',
294	      'API_RATE_LIMIT_WINDOW_SECONDS',
295	      // HU-09-02 RN-12: 60 requests por minuto, por cuenta y por endpoint.
296	      { enabled: true, max: 60, windowSeconds: 60 },
297	      false,
298	    ),
299	    registerRateLimit: rateLimitFrom(
300	      env,
301	      'REGISTER_RATE_LIMIT_ENABLED',
302	      'REGISTER_RATE_LIMIT_MAX',
303	      'REGISTER_RATE_LIMIT_WINDOW_SECONDS',
304	      // HU-01-01 RN-10: opcional; desactivado salvo configuración explícita del entorno.
305	      { enabled: false, max: 20, windowSeconds: 60 },
306	      true,
307	    ),
308	    loginRateLimit: rateLimitFrom(
309	      env,
310	      'LOGIN_RATE_LIMIT_ENABLED',
311	      'LOGIN_RATE_LIMIT_MAX_FAILURES',
312	      'LOGIN_RATE_LIMIT_WINDOW_SECONDS',
313	      // HU-01-02 RN-9: opcional; cuenta intentos fallidos por (origen, email).
314	      { enabled: false, max: 5, windowSeconds: 60 },
315	      true,
316	    ),
317	    internalApiToken: env.INTERNAL_API_TOKEN?.trim() || undefined,
318	    corsAllowedOrigins: parseCorsAllowedOrigins(env.CORS_ALLOWED_ORIGINS),
319	    logLevel: env.LOG_LEVEL?.trim() || 'info',
320	  };
321	}

