  2	 * Servicio de cuentas: registro (HU-01-01) e inicio de sesión (HU-01-02).
  3	 *
  4	 * Las precedencias de validación son deterministas y se reporta **un solo error** por
  5	 * respuesta (RNE-7 / modelo-de-errores.md §4).
  6	 */
  7	import { randomUUID } from 'node:crypto';
  8	import { AppError, validationError, type ValidationIssue } from '../../core/errors';
  9	import { dummyVerify, hashPassword, verifyPassword } from '../../core/password';
 10	import { nowIso } from '../../core/time';
 11	import {
 12	  EMAIL_MAX_LENGTH,
 13	  PASSWORD_MAX_LENGTH,
 14	  PASSWORD_MIN_LENGTH,
 15	  characterLength,
 16	  isValidEmailFormat,
 17	  normalizeEmail,
 18	} from '../../core/validation';
 19	import { isUniqueConstraintError, transaction, type Db } from '../../db/index';
 20	import type { AuditLog } from '../../core/audit';
 21	import { AccountRepository } from './repository';
 22	import type { SessionService } from './sessions';
 23	
 24	/** Proyección pública de una cuenta (nunca incluye password, hash ni sal — RNE-2). */
 25	export interface AccountView {
 26	  accountId: string;
 27	  email: string;
 28	  status: string;
 29	  createdAt: string;
 30	}
 31	
 32	export interface LoginResult {
 33	  token: string;
 34	  tokenType: 'Bearer';
 35	  expiresAt: string;
 36	}
 37	
 38	/** Contrato mínimo con la épica 06: asignación eager de dirección al alta (HU-06-03 RN-12). */
 39	export interface DepositAddressAssigner {
 40	  /** Se ejecuta **dentro** de la transacción de alta de la cuenta. */
 41	  assignForAccountInTransaction(accountId: string): void;
 42	  /** Se ejecuta después del commit: publica el evento de dominio. */
 43	  publishPendingEvents(): void;
 44	}
 45	
 46	function isPlainObject(value: unknown): value is Record<string, unknown> {
 47	  return typeof value === 'object' && value !== null && !Array.isArray(value);
 48	}
 49	
 50	/**
 51	 * Paso 1 de la precedencia: esquema/tipos/campos requeridos/campos desconocidos
 52	 * (HU-01-01 RN-4/RN-9).
 53	 */
 54	export function parseRegisterPayload(body: unknown): { email: string; password: string } {
 55	  if (!isPlainObject(body)) {
 56	    throw validationError([{ field: 'body', message: 'El cuerpo debe ser un objeto JSON.' }]);
 57	  }
 58	  const issues: ValidationIssue[] = [];
 59	  const allowed = new Set(['email', 'password']);
 60	  for (const key of Object.keys(body)) {
 61	    if (!allowed.has(key)) {
 62	      issues.push({ field: key, message: 'Campo desconocido.' });
 63	    }
 64	  }
 65	  if (!('email' in body)) {
 66	    issues.push({ field: 'email', message: 'Campo requerido faltante.' });
 67	  } else if (typeof body.email !== 'string') {
 68	    issues.push({ field: 'email', message: 'Debe ser un string.' });
 69	  }
 70	  if (!('password' in body)) {
 71	    issues.push({ field: 'password', message: 'Campo requerido faltante.' });
 72	  } else if (typeof body.password !== 'string') {
 73	    issues.push({ field: 'password', message: 'Debe ser un string.' });
 74	  }
 75	  if (issues.length > 0) throw validationError(issues);
 76	  return { email: body.email as string, password: body.password as string };
 77	}
 78	
 79	/** Paso 1 del login: sólo tipos (HU-01-02 RN-7/RN-11: no se valida el formato del email). */
 80	export function parseLoginPayload(body: unknown): { email: string; password: string } {
 81	  if (!isPlainObject(body)) {
 82	    throw validationError([{ field: 'body', message: 'El cuerpo debe ser un objeto JSON.' }]);
 83	  }
 84	  const issues: ValidationIssue[] = [];
 85	  if (!('email' in body)) {
 86	    issues.push({ field: 'email', message: 'Campo requerido faltante.' });
 87	  } else if (typeof body.email !== 'string') {
 88	    issues.push({ field: 'email', message: 'Debe ser un string.' });
 89	  }
 90	  if (!('password' in body)) {
 91	    issues.push({ field: 'password', message: 'Campo requerido faltante.' });
 92	  } else if (typeof body.password !== 'string') {
 93	    issues.push({ field: 'password', message: 'Debe ser un string.' });
 94	  }
 95	  if (issues.length > 0) throw validationError(issues);
 96	  return { email: body.email as string, password: body.password as string };
 97	}
 98	
 99	export class AccountService {
100	  private readonly accounts: AccountRepository;
101	
102	  constructor(
103	    private readonly db: Db,
104	    private readonly sessions: SessionService,
105	    private readonly audit: AuditLog,
106	    private readonly addressAssigner: DepositAddressAssigner,
107	  ) {
108	    this.accounts = new AccountRepository(db);
109	  }
110	
111	  get repository(): AccountRepository {
112	    return this.accounts;
113	  }
114	
115	  /** HU-01-01: alta de cuenta. Devuelve la proyección pública (sin secretos). */
116	  async register(body: unknown, origin: string | null): Promise<AccountView> {
117	    // Paso 1: esquema.
118	    const payload = parseRegisterPayload(body);
119	    // Paso 2: formato de email (sobre el email normalizado, RN-1/RN-2).
120	    const email = normalizeEmail(payload.email);
121	    if (!isValidEmailFormat(email)) {
122	      this.audit.record({
123	        event: 'REGISTER',
124	        email,
125	        result: 'FAILURE',
126	        reason: 'VALIDATION_ERROR',
127	        origin,
128	      });
129	      throw validationError([
130	        {
131	          field: 'email',
132	          message: `Formato de email inválido o de más de ${EMAIL_MAX_LENGTH} caracteres.`,
133	        },
134	      ]);
135	    }
136	    // Paso 3: política de contraseña. El rango es de **caracteres** (RN-3), por lo que se
137	    // cuentan code points y no unidades UTF-16.
138	    const passwordLength = characterLength(payload.password);
139	    if (passwordLength < PASSWORD_MIN_LENGTH || passwordLength > PASSWORD_MAX_LENGTH) {
140	      this.audit.record({
141	        event: 'REGISTER',
142	        email,
143	        result: 'FAILURE',
144	        reason: 'VALIDATION_ERROR',
145	        origin,
146	      });
147	      throw validationError([
148	        {
149	          field: 'password',
150	          message: `La contraseña debe tener entre ${PASSWORD_MIN_LENGTH} y ${PASSWORD_MAX_LENGTH} caracteres.`,
151	        },
152	      ]);
153	    }
154	
155	    const passwordHash = await hashPassword(payload.password);
156	    const account: AccountView & { passwordHash: string } = {
157	      accountId: randomUUID(), // opaco, no secuencial, 122 bits de entropía (RN-6 / RNE-6)
158	      email,
159	      status: 'ACTIVE',
160	      createdAt: nowIso(),
161	      passwordHash,
162	    };
163	
164	    // Paso 4: unicidad. La restricción UNIQUE de la base resuelve también el caso
165	    // concurrente (RN-8): a lo sumo una inserción prospera.
166	    try {
167	      transaction(this.db, () => {
168	        this.accounts.insert({
169	          accountId: account.accountId,
170	          email: account.email,
171	          passwordHash,
172	          status: account.status,
173	          createdAt: account.createdAt,
174	        });
175	        this.accounts.insertInitialBalances(account.accountId);
176	        // Asignación eager de la dirección de depósito (HU-06-03 RN-12), en la misma
177	        // transacción: no existe una cuenta sin dirección observable.
178	        this.addressAssigner.assignForAccountInTransaction(account.accountId);
179	      });
180	    } catch (err) {
181	      if (isUniqueConstraintError(err)) {
182	        this.audit.record({
183	          event: 'REGISTER',
184	          email,
185	          result: 'FAILURE',
186	          reason: 'EMAIL_ALREADY_EXISTS',
187	          origin,
188	        });
189	        throw new AppError('EMAIL_ALREADY_EXISTS', 'Ya existe una cuenta con ese email.', {
190	          email,
191	        });
192	      }
193	      throw err;
194	    }
195	
196	    this.addressAssigner.publishPendingEvents();
197	    this.audit.record({ event: 'REGISTER', email, result: 'SUCCESS', origin });
198	
199	    return {
200	      accountId: account.accountId,
201	      email: account.email,
202	      status: account.status,
203	      createdAt: account.createdAt,
204	    };
205	  }
206	
207	  /** HU-01-02: verificación de credenciales y emisión del token de sesión. */
208	  async login(body: unknown, origin: string | null): Promise<LoginResult> {
209	    // Paso 1: esquema (sin validar el formato del email — RN-11).
210	    const payload = parseLoginPayload(body);
211	    const email = normalizeEmail(payload.email);
212	    const account = this.accounts.findByEmail(email);
213	
214	    let ok = false;
215	    if (account) {
216	      ok = await verifyPassword(payload.password, account.passwordHash);
217	    } else {
218	      // Email inexistente: se ejecuta un KDF dummy de coste equivalente para que la
219	      // latencia no permita enumerar cuentas (RN-12 / RNE-3).
220	      await dummyVerify(payload.password);
221	    }
222	
223	    if (!account || !ok) {
224	      this.audit.record({
225	        event: 'LOGIN',
226	        email,
227	        result: 'FAILURE',
228	        reason: 'INVALID_CREDENTIALS',
229	        origin,
230	      });
231	      // Respuesta idéntica tanto si el email no existe como si la contraseña es
232	      // incorrecta, y sin `details` discriminante (RN-2).
233	      throw new AppError('INVALID_CREDENTIALS', 'Credenciales inválidas.');
234	    }
235	
236	    const session = this.sessions.issue(account.accountId);
237	    this.audit.record({ event: 'LOGIN', email, result: 'SUCCESS', origin });
238	    return { token: session.token, tokenType: 'Bearer', expiresAt: session.expiresAt };
239	  }
240	}

