export interface AppDependencies {
  config: Config;
  db: Db;
  accounts: AccountService;
  sessions: SessionService;
  wallet: WalletService;
  audit: AuditLog;
}

/** Verbos soportados por cada ruta existente (para responder 405 y no 404). */
const ROUTE_METHODS: Record<string, string[]> = {
  '/health': ['GET', 'HEAD'],
  '/api/v1/auth/register': ['POST'],
  '/api/v1/auth/login': ['POST'],
  '/api/v1/me': ['GET', 'HEAD'],
  '/api/v1/deposit-address': ['GET', 'HEAD'],
  '/internal/deposit-addresses': ['GET', 'HEAD'],
};

const SUPPORTED_ASSETS = ['ETH', 'USDC'] as const;
type SupportedAsset = (typeof SUPPORTED_ASSETS)[number];

function normalizePath(url: string): string {
  const pathname = url.split('?')[0];
  if (pathname.length > 1 && pathname.endsWith('/')) return pathname.slice(0, -1);
  return pathname;
}

/**
 * Error de parseo del cuerpo diferido hasta después del paso 0 de la precedencia
 * (rate limiting) y de la autenticación. Se guarda en la request bajo un símbolo propio.
 */
const DEFERRED_BODY_ERROR = Symbol('deferredBodyError');

type RequestWithDeferredError = { [DEFERRED_BODY_ERROR]?: AppError };

function deferBodyError(request: unknown, error: AppError): void {
  (request as RequestWithDeferredError)[DEFERRED_BODY_ERROR] = error;
}

/** Levanta el error de parseo diferido, si lo hubo. */
        request,
        validationError([{ field: 'body', message: 'El cuerpo no es JSON válido.' }]),
      );
      done(null, undefined);
    }
  });

  // Rutas cuyo handler levanta el error diferido en el punto exacto que le fija su
  // precedencia (después del rate limiting y de la autenticación). Para cualquier otra
  // ruta, la red de seguridad de abajo lo levanta antes del handler, de modo que un cuerpo
  // que no parsea nunca se ignora en silencio.
  const ROUTES_WITH_ORDERED_BODY_CHECK = new Set([
    '/api/v1/auth/register',
    '/api/v1/auth/login',
    '/api/v1/me',
    '/api/v1/deposit-address',
    '/internal/deposit-addresses',
  ]);
  app.addHook('preHandler', async (request) => {
    if (ROUTES_WITH_ORDERED_BODY_CHECK.has(normalizePath(request.url))) return;
    throwDeferredBodyError(request);
  });

  // ---------------------------------------------------------------------------
  // Manejo uniforme de errores (HU-09-05).
  // ---------------------------------------------------------------------------
  function sendError(reply: FastifyReply, error: AppError): FastifyReply {
    if (error.headers) {
      for (const [name, value] of Object.entries(error.headers)) reply.header(name, value);
    }
    return reply.status(error.httpStatus).send(error.toEnvelope());
  }

  app.setErrorHandler((error, request, reply) => {
    if (error instanceof AppError) {
      return sendError(reply, error);
    }
    const fastifyCode = (error as { code?: string }).code ?? '';
    if (
      fastifyCode.startsWith('FST_ERR_CTP_') ||
      fastifyCode === 'FST_ERR_VALIDATION' ||
      (typeof (error as { statusCode?: number }).statusCode === 'number' &&
        (error as { statusCode: number }).statusCode === 400)
    ) {
      return sendError(
        reply,
        validationError([{ field: 'body', message: 'Cuerpo o parámetros inválidos.' }]),
      );
    }
    // INTERNAL_ERROR no filtra detalles sensibles (HU-09-05 RN-9); el detalle queda en el
    // log del servidor.

