// Verificación INDEPENDIENTE del SUT de MNEMONIC_24_VALIDO, implementando
// bip-0039.mediawiki §"Generating the mnemonic" con el wordlist del corpus.
const crypto = require('node:crypto');
const fs = require('node:fs');
const WL = '/private/tmp/eval-wb-celda-en-evaluacion-p2-20260824-124646/corpus/documentos/bip-0039-wordlist-english.txt';
const words = fs.readFileSync(WL, 'utf8').split('\n').map(s => s.trim()).filter(Boolean);
console.log('wordlist words =', words.length);
const ent = Buffer.alloc(32, 0x00);                 // entropía 0x00 * 32 (ENT = 256)
const cs = crypto.createHash('sha256').update(ent).digest();
const CS = 256 / 32;                                 // 8 bits de checksum
let bits = '';
for (const b of ent) bits += b.toString(2).padStart(8, '0');
bits += cs[0].toString(2).padStart(8, '0').slice(0, CS);
const out = [];
for (let i = 0; i < bits.length; i += 11) out.push(words[parseInt(bits.slice(i, i + 11), 2)]);
console.log('MS =', out.length);
console.log('MNEMONIC_24_VALIDO =', out.join(' '));
console.log('ultima palabra =', out[23]);
EOF
node /tmp/eval-wb/drivers/verificar-constante.js

