// Si el cuerpo no parseó no hay email: el paso 0 se evalúa igual, con el origen como
// granularidad, para que una solicitud con payload inválido responda 429 y no 422
// (HU-01-02 RN-8).
const decision =
  rawEmail === ''
    ? loginFailureLimiter.peekByPrefix(`${request.ip}|`)
    : loginFailureLimiter.peek(limiterKey);
if (decision.limited) {
  audit.record({
    event: 'LOGIN',
    email: rawEmail || null,
    result: 'FAILURE',
    reason: 'RATE_LIMITED',
    origin: request.ip ?? null,
  });
  throw new AppError(
    'RATE_LIMITED',
    'Se superó el límite de intentos de autenticación.',
    { retryAfterSeconds: decision.retryAfterSeconds },
    { 'Retry-After': String(decision.retryAfterSeconds) },
  );

